  {
    "name": "google_calendar_find_calendars",
    "description": "Find calendars matching criteria.\n\nArgs:\n    showHidden: Include hidden calendars in results.\n    showDeleted: Include deleted calendars in results.\n    minAccessRole: Only include calendars with at least this access level.\n\nReturns:\n    JSON string with matching calendars.",
    "parameters": {
      "properties": {
        "showHidden": {
          "default": false,
          "description": "Include hidden calendars in results.",
          "title": "Showhidden",
          "type": "boolean"
        },
        "showDeleted": {
          "default": false,
          "description": "Include deleted calendars in results.",
          "title": "Showdeleted",
          "type": "boolean"
        },
        "minAccessRole": {
          "anyOf": [
            {
              "enum": [
                "freeBusyReader",
                "reader",
                "writer",
                "owner"
              ],
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Only include calendars with at least this access level.",
          "title": "Minaccessrole"
        }
      },
      "title": "google_calendar_find_calendars_args",
      "type": "object",
      "additionalProperties": false,
      "required": [
        "showHidden",
        "showDeleted",
        "minAccessRole"
      ]
    }
  },
